try:
    import openpyxl
    print("openpyxl OK:", openpyxl.__version__)
except Exception as e:
    print("import failed:", e)

import sys
from copy import copy
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

path = sys.argv[1] if len(sys.argv) > 1 else "sales_data.xlsx"
wb = load_workbook(path)
ws = wb.active


def find_header_row(sheet):
    for row in sheet.iter_rows(min_row=1, max_row=10):
        if any(isinstance(c.value, str) and c.value.strip() for c in row):
            return row[0].row
    return 1


header_row = find_header_row(ws)
norm = {}
for c in ws[header_row]:
    if c.value is not None:
        norm[str(c.value).strip().lower()] = c.column


def find_col(*names):
    for n in names:
        if n in norm:
            return norm[n]
    return None


rev_col = find_col("revenue", "sales", "total revenue", "sales revenue", "total sales", "revenue (usd)")
profit_col = find_col("profit", "net profit", "gross profit", "net income", "operating profit", "income", "profit after tax")
cost_col = find_col("cost", "cogs", "cost of goods sold", "cost of sales", "total cost", "expenses", "total expenses")

if rev_col is None:
    raise SystemExit(f"error: no revenue/sales column found. headers: {norm}")
if profit_col is None and cost_col is None:
    raise SystemExit(f"error: need a profit or cost column. headers: {norm}")

rev_letter = get_column_letter(rev_col)
if profit_col is not None:
    num_letter = get_column_letter(profit_col)
    expr = lambda r: f"{num_letter}{r}/{rev_letter}{r}"
else:
    num_letter = get_column_letter(cost_col)
    expr = lambda r: f"({rev_letter}{r}-{num_letter}{r})/{rev_letter}{r}"

new_col = ws.max_column + 1
new_letter = get_column_letter(new_col)

src = ws.cell(row=header_row, column=1)
hdr = ws.cell(row=header_row, column=new_col, value="Profit Margin (%)")
if src.has_style:
    hdr.font = copy(src.font)
    hdr.fill = copy(src.fill)
    hdr.border = copy(src.border)
    hdr.alignment = copy(src.alignment)

count = 0
for r in range(header_row + 1, ws.max_row + 1):
    if ws.cell(row=r, column=rev_col).value is None:
        continue
    if ws.cell(row=r, column=(profit_col or cost_col)).value is None:
        continue
    c = ws.cell(row=r, column=new_col, value=f"=IFERROR({expr(r)},\"\")")
    c.number_format = "0.0%"
    count += 1

if rev_letter in ws.column_dimensions:
    ws.column_dimensions[new_letter].width = ws.column_dimensions[rev_letter].width

wb.save(path)
print(f"ok: header_row={header_row} revenue_col={rev_letter} numerator_col={num_letter} new_col={new_letter} rows_filled={count}")

